<script setup lang="ts">
import {computed,ref,shallowRef,watch} from 'vue'
import {ApiError} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {formatTime} from '@/core/time'
import {useResource} from '@/core/use-resource'
import AsyncState from '@/ui/AsyncState.vue'
import CursorPager from '@/ui/CursorPager.vue'
import FirmwareUpload from './OtaFirmwareUpload.vue'
import FirmwarePublication from './OtaFirmwarePublication.vue'
import FirmwareMetadata from './OtaFirmwareMetadataEditor.vue'
import FirmwareEnablement from './OtaFirmwareEnablement.vue'
import FirmwareExecutionBinding from './OtaFirmwareExecutionBinding.vue'
import FirmwareVersionDistribution from './OtaFirmwareVersionDistribution.vue'
import FirmwareUpgradeStatistics from './OtaFirmwareUpgradeStatistics.vue'
import FirmwareManualDispatch from './OtaFirmwareManualDispatch.vue'
import FirmwareDeletion from './OtaFirmwareDeletion.vue'
import type {OtaUpgradeDevice} from './ota-upgrade-statistics-api'
import type {OtaManualDispatchMode} from './ota-manual-dispatch-api'
import {otaUpgradeStatisticsTransport,otaUpgradeReasonLabel,type OtaUpgradeMetric} from './ota-upgrade-statistics-api'
import {typeDeviceUuid,type TypeDeviceQuery} from '../device-types/type-devices-api'
import {firmwareStatusLabel,uploadStatusLabel,formatBytes} from '../../../../../things-link-console/src/features/ota/firmware-model'
import {otaReadTransport,type OtaReadTransport,type OtaUpload} from './ota-read-api'
const props=withDefaults(defineProps<{firmwareId:string;transport?:OtaReadTransport}>(),{transport:()=>otaReadTransport})
const emit=defineEmits<{locked:[boolean];changed:[];deleted:[id:string]}>()
const uploadMount=ref<HTMLElement>(),publicationMount=ref<HTMLElement>(),overviewMetadataMount=ref<HTMLElement>(),settingsMetadataMount=ref<HTMLElement>(),enablementMount=ref<HTMLElement>(),deletionMount=ref<HTMLElement>()
const manual=shallowRef<InstanceType<typeof FirmwareManualDispatch>>(),statisticsRefresh=ref(0)
const activeTab=ref('overview'),statisticsMetric=ref<OtaUpgradeMetric>('ALL_RELATED')
function openStatistics(metric:OtaUpgradeMetric){if(!manager.value)return;statisticsMetric.value=metric;activeTab.value='statistics'}
const uploading=ref(false),publishing=ref(false),editingMetadata=ref(false),changingEnablement=ref(false),dispatching=ref(false),deleting=ref(false)
watch([uploading,publishing,editingMetadata,changingEnablement,dispatching,deleting],()=>emit('locked',uploading.value||publishing.value||editingMetadata.value||changingEnablement.value||dispatching.value||deleting.value),{flush:'sync'})
const roles=['OWNER','ADMIN','OPERATOR','VIEWER'],readable=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.firmwareId)&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||''))
const manager=computed(()=>readable.value&&can('ota:read')&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||'')),targetsAllowed=computed(()=>manager.value&&can('device:read'))
const keyword=ref(''),online=ref<''|'ONLINE'|'OFFLINE'>(''),query=ref<TypeDeviceQuery>({page:1,limit:24}),device=ref('')
const firmware=useResource(signal=>props.transport.firmware(projectId.value,props.firmwareId,signal))
const recount=useResource(signal=>{if(!manager.value||!firmware.data.value)throw new Error('当前没有统计读取权限');return otaUpgradeStatisticsTransport.read(projectId.value,firmware.data.value,signal)})
function recountNow(){if(!manager.value||!firmware.data.value||recount.loading.value)return;recount.clear();void recount.reload()}
const metadata=useResource(signal=>{if(!manager.value||!firmware.data.value)throw new Error('当前没有管理元数据读取权限');return props.transport.metadata(projectId.value,firmware.data.value,signal)})
// 元数据刷新不销毁发布原意图；缓存仅属于当前固件，失权或范围变化即清理。
const retainedUploads=shallowRef<readonly OtaUpload[]>(),publicationUploads=computed(()=>metadata.data.value?.uploads.items??retainedUploads.value)
watch(()=>metadata.error.value,value=>{if(value instanceof ApiError&&[401,403].includes(value.status))retainedUploads.value=undefined},{flush:'sync'})
const targets=useResource(signal=>{if(!targetsAllowed.value||!firmware.data.value)throw new Error('当前没有设备候选读取权限');return props.transport.targets(projectId.value,firmware.data.value,query.value,signal)})
const eligibility=useResource(signal=>{if(!manager.value||!device.value||!firmware.data.value)throw new Error('请选择本页设备核对资格');return props.transport.eligibility(projectId.value,firmware.data.value.id,device.value,signal)})
const forbidden=computed(()=>!readable.value||firmware.error.value instanceof ApiError&&[401,403].includes(firmware.error.value.status))
const reasons:Record<string,string>={ELIGIBLE:'本次快照满足资格',REPORT_MISSING:'尚无设备能力报告',REPORT_STALE:'设备能力报告已过期',IDENTITY_CHANGED:'设备身份或绑定已变化',INCOMPATIBLE:'能力、安全边界或模型不兼容',TRUST_NOT_ACKNOWLEDGED:'尚未确认当前信任包',FIRMWARE_UNAVAILABLE:'固件发布当前不可用',FIRMWARE_DISABLED:'该固件版本当前未启用',VERSION_UNCONFIRMED:'尚未确认设备实际运行版本',VERSION_NOT_NEWER:'目标版本不高于设备当前版本',TARGET_CONDITIONS_NOT_MATCHED:'设备不符合该版本当前指定的升级条件'}
function openDispatch(row:OtaUpgradeDevice,mode:OtaManualDispatchMode){if(!manager.value||uploading.value||publishing.value||editingMetadata.value||changingEnablement.value||dispatching.value||deleting.value||!firmware.data.value||row.currentEligible!==true||!row.current||mode!==(row.relatedState==='NOT_DELIVERED'?'INITIAL':row.relatedState==='DELIVERED_NOT_SUCCEEDED'?'REDISPATCH':undefined))return;manual.value?.open(row.deviceId,mode,row.current.name)}
function dispatchAccepted(){statisticsRefresh.value++;emit('changed')}
function clearSecondary(preservePublication=false){recount.clear();retainedUploads.value=preservePublication?publicationUploads.value:undefined;metadata.clear();targets.clear();eligibility.clear();device.value='';keyword.value='';online.value='';query.value={page:1,limit:24}}
function reset(){activeTab.value='overview';statisticsMetric.value='ALL_RELATED';statisticsRefresh.value=0;firmware.clear();clearSecondary();if(readable.value)void firmware.reload()}
function loadMetadata(){if(publishing.value||editingMetadata.value||changingEnablement.value||dispatching.value||deleting.value||!manager.value||!firmware.data.value||metadata.loading.value)return;if(metadata.data.value)retainedUploads.value=metadata.data.value.uploads.items;metadata.clear();void metadata.reload()}
function loadTargets(){if(!targetsAllowed.value||!firmware.data.value||targets.loading.value)return;eligibility.clear();device.value='';targets.clear();void targets.reload()}
function filter(){if(targets.loading.value||!targetsAllowed.value||keyword.value.trim().length>128)return;query.value={page:1,limit:24,keyword:keyword.value.trim()||undefined,online:online.value};loadTargets()}
function turn(page:number){if(!targetsAllowed.value||targets.loading.value||page<1||page>10000||!Number.isSafeInteger(page))return;query.value={...query.value,page};loadTargets()}
function check(id:string){if(!manager.value||eligibility.loading.value||!targets.data.value?.items.some(item=>item.id===id))return;eligibility.clear();device.value=id;void eligibility.reload()}
watch([()=>projectId.value,()=>props.firmwareId,()=>session.user?.accountId,()=>readable.value,()=>props.transport],reset,{immediate:true,flush:'sync'})
watch([()=>manager.value,()=>targetsAllowed.value],()=>{if(!manager.value)activeTab.value='overview';clearSecondary(publishing.value&&readable.value)},{flush:'sync'})
</script>
<template><section class="ota-firmware-detail"><AsyncState :forbidden="forbidden" :loading="firmware.loading.value" :error="firmware.error.value" @retry="reset"><template v-if="firmware.data.value"><el-tabs v-model="activeTab"><el-tab-pane label="概览" name="overview"><div ref="overviewMetadataMount"/><FirmwareExecutionBinding :firmware="firmware.data.value"/><template v-if="manager"><FirmwareUpgradeStatistics :firmware="firmware.data.value" :active="activeTab==='overview'" overview :refresh-key="statisticsRefresh" :disabled="uploading||publishing||editingMetadata||changingEnablement||dispatching||deleting" @dispatch="openDispatch" @open="openStatistics"/><FirmwareVersionDistribution :firmware="firmware.data.value" :active="activeTab==='overview'" summary @more="activeTab='versions'"/></template><details><summary>固件详细信息</summary><dl class="facts"><dt>固件版本</dt><dd>{{firmware.data.value.firmwareVersion}}</dd><dt>固件 ID</dt><dd>{{firmware.data.value.id}}</dd><dt>固件状态</dt><dd>{{firmwareStatusLabel(firmware.data.value.status)}}</dd><dt>修订</dt><dd>{{firmware.data.value.revision}}</dd><dt>设备类型 ID</dt><dd>{{firmware.data.value.deviceTypeId}}</dd><dt>固定模型版本 ID</dt><dd>{{firmware.data.value.thingModelVersionId}}</dd><dt>产品标识</dt><dd>{{firmware.data.value.productKey}}</dd><dt>模型摘要</dt><dd>{{firmware.data.value.schemaDigest}}</dd><dt>摘要算法</dt><dd>{{firmware.data.value.schemaDigestAlgorithm}}</dd><dt>创建时间</dt><dd>{{formatTime(firmware.data.value.createdAt)}}</dd></dl></details>
 <p class="help">以上为固件保存的固定绑定与当前服务端状态，不代表任一设备已经下载或安装。</p>
 <div ref="uploadMount"/>
 <details class="advanced-publication"><summary>高级发布与诊断</summary>
 <template v-if="manager"><h3>发布资料与历史</h3><p class="help">按当前固件读取最新 20 条上传会话、发布尝试及同类型基线历史；不展示对象地址、凭据或私钥，也不创建任何操作。</p><el-button size="small" :loading="metadata.loading.value" :disabled="publishing||editingMetadata||changingEnablement||dispatching||deleting" @click="loadMetadata">读取管理元数据</el-button><AsyncState :loading="metadata.loading.value" :error="metadata.error.value" @retry="loadMetadata"><template v-if="metadata.data.value"><h4>上传会话</h4><el-empty v-if="!metadata.data.value.uploads.items.length" description="尚无上传会话" :image-size="48"/><el-table v-else :data="metadata.data.value.uploads.items" border><el-table-column prop="id" label="会话 ID" min-width="220"/><el-table-column label="状态"><template #default="{row}">{{uploadStatusLabel(row.status)}}</template></el-table-column><el-table-column label="预期字节数"><template #default="{row}">{{formatBytes(row.expectedLength)}}</template></el-table-column><el-table-column prop="expectedSha256" label="预期制品摘要" min-width="200"/></el-table><p v-if="metadata.data.value.uploads.hasMore" class="help">还有更早的上传记录，本次仅展示最新一页。</p><h4>发布尝试</h4><el-empty v-if="!metadata.data.value.publications.items.length" description="尚无发布尝试" :image-size="48"/><el-table v-else :data="metadata.data.value.publications.items" border><el-table-column prop="id" label="尝试 ID" min-width="220"/><el-table-column prop="status" label="持久状态"/><el-table-column prop="failureCode" label="失败分类"/><el-table-column label="更新于"><template #default="{row}">{{formatTime(row.updatedAt)}}</template></el-table-column></el-table><p v-if="metadata.data.value.publications.hasMore" class="help">还有更早的发布尝试，本次仅展示最新一页。</p><p class="help">接受尝试或 PREPARED 不表示固件就绪；就绪也不表示设备已安装。</p><h4>同类型基线历史</h4><el-empty v-if="!metadata.data.value.baselines.items.length" description="尚无已登记基线" :image-size="48"/><el-table v-else :data="metadata.data.value.baselines.items" border><el-table-column prop="baselineVersion" label="基线版本"/><el-table-column prop="baselineHash" label="规范摘要" min-width="220"/><el-table-column label="登记于"><template #default="{row}">{{formatTime(row.registeredAt)}}</template></el-table-column></el-table><p v-if="metadata.data.value.baselines.hasMore" class="help">还有更早的基线，本次仅展示最新一页。</p></template></AsyncState>
 <h3>目标设备只读核对</h3><p class="help">候选固定为该固件的设备类型，可按当前项目设备目录筛选。同类型、在线或已选中均不代表兼容；逐台读取资格只证明检查时刻的交集，不创建活动或派发授权。</p>
 <form v-if="targetsAllowed" class="target-filter" @submit.prevent="filter"><el-input v-model="keyword" aria-label="OTA目标设备关键词" placeholder="按名称或标识读取设备" maxlength="128"/><el-select v-model="online" aria-label="OTA目标设备连接状态"><el-option value="" label="不限连接状态"/><el-option value="ONLINE" label="在线"/><el-option value="OFFLINE" label="离线"/></el-select><el-button native-type="submit" :loading="targets.loading.value">读取候选设备</el-button></form><p v-else class="help">当前未授予设备读取权限，不能列出候选设备。</p>
 <AsyncState v-if="targetsAllowed" :loading="targets.loading.value" :error="targets.error.value" @retry="loadTargets"><template v-if="targets.data.value"><p>候选总数：{{targets.data.value.total}} · 第 {{query.page}} 页</p><el-empty v-if="!targets.data.value.items.length" description="当前条件无候选设备" :image-size="48"/><el-table v-else :data="targets.data.value.items" border><el-table-column prop="name" label="设备名称"/><el-table-column prop="id" label="设备 ID" min-width="220"/><el-table-column prop="status" label="连接状态"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" :disabled="eligibility.loading.value" @click="check(row.id)">核对当前资格</el-button></template></el-table-column></el-table><CursorPager :page="query.page" :limit="24" :total="targets.data.value.total" :loading="targets.loading.value" :show-sizes="false" @update:page="turn"/></template></AsyncState>
 <AsyncState :loading="eligibility.loading.value" :error="eligibility.error.value" @retry="check(device)"><template v-if="eligibility.data.value"><p role="status">设备 {{device}}：{{reasons[eligibility.data.value.reason]||eligibility.data.value.reason}}</p><p class="help">检查时间：{{formatTime(eligibility.data.value.checkedAt)}} · 报告修订：{{eligibility.data.value.reportRevision??'尚无'}}；该结果不是设备安装结果。</p></template></AsyncState>
 </template><p v-else class="help">当前角色可读取固件历史；管理元数据和设备资格核对仅向有 OTA 读取权限的 OWNER/ADMIN 展示。</p>
 <div ref="publicationMount"/>
 </details>
 </el-tab-pane><el-tab-pane v-if="manager" label="版本分布" name="versions"><FirmwareVersionDistribution :firmware="firmware.data.value" :active="activeTab==='versions'"/></el-tab-pane><el-tab-pane v-if="manager" label="升级统计" name="statistics"><FirmwareUpgradeStatistics :firmware="firmware.data.value" :active="activeTab==='statistics'" :initial-metric="statisticsMetric" :refresh-key="statisticsRefresh" :disabled="uploading||publishing||editingMetadata||changingEnablement||dispatching||deleting" @dispatch="openDispatch" @open="openStatistics"/></el-tab-pane><el-tab-pane v-if="manager" label="设置" name="settings"><div ref="settingsMetadataMount"/><div ref="enablementMount"/><section class="statistics-settings"><h3>升级状态统计</h3><p class="help">按最新已确认记录重新计算，不触发设备回报或安装核对。</p><el-button :loading="recount.loading.value" @click="recountNow">重新统计升级状态</el-button><AsyncState :loading="recount.loading.value" :error="recount.error.value" @retry="recountNow"><template v-if="recount.data.value"><p role="status">已按最新确认记录重新统计，观察时间：{{formatTime(recount.data.value.observedAt)}}</p><p v-if="recount.data.value.eligibilityState==='UNAVAILABLE'" class="help">当前可升级范围仍未确认：{{otaUpgradeReasonLabel(recount.data.value.eligibilityReason!)}}</p><p class="help">成功仍按平台确认的受保护安装结果计算；仅上报目标版本不计为安装成功。</p><el-button link type="primary" @click="openStatistics('ALL_RELATED')">查看升级统计</el-button></template></AsyncState></section><div ref="deletionMount"/></el-tab-pane></el-tabs></template></AsyncState><FirmwareUpload portal :firmware-id="firmwareId" :firmware="firmware.data.value" :target="uploadMount" :disabled="publishing||editingMetadata||changingEnablement||dispatching||deleting" @locked="uploading=$event" @changed="loadMetadata"/><FirmwarePublication portal :firmware-id="firmwareId" :firmware="firmware.data.value" :target="publicationMount" :uploads="publicationUploads" :disabled="uploading||editingMetadata||changingEnablement||dispatching||deleting" @locked="publishing=$event" @changed="reset"/><FirmwareMetadata :firmware-id="firmwareId" portal :overview-target="overviewMetadataMount" :settings-target="settingsMetadataMount" edit-label="编辑" :disabled="uploading||publishing||changingEnablement||dispatching||deleting" @locked="editingMetadata=$event" @changed="$emit('changed')"/><FirmwareEnablement portal :firmware-id="firmwareId" :status="firmware.data.value?.status" :target="enablementMount" :disabled="uploading||publishing||editingMetadata||dispatching||deleting" @locked="changingEnablement=$event" @changed="$emit('changed')"/><FirmwareManualDispatch ref="manual" :firmware-id="firmwareId" :disabled="uploading||publishing||editingMetadata||changingEnablement||deleting" @locked="dispatching=$event" @accepted="dispatchAccepted"/><FirmwareDeletion portal :firmware-id="firmwareId" :target="deletionMount" :disabled="uploading||publishing||editingMetadata||changingEnablement||dispatching" @locked="deleting=$event" @deleted="$emit('deleted',firmwareId)"/></section></template>
<style scoped>.advanced-publication{margin-top:20px;border-top:1px solid var(--tl-border);padding-top:14px}.advanced-publication>summary{cursor:pointer;font-size:13px;color:var(--tl-muted)}.facts{display:grid;grid-template-columns:135px minmax(0,1fr);gap:10px 16px;font-size:13px;line-height:20px}.facts dt{color:var(--tl-muted)}.facts dd{margin:0;overflow-wrap:anywhere}.help{font-size:12px;line-height:20px;color:var(--tl-muted);overflow-wrap:anywhere}.target-filter{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.target-filter .el-input{width:260px}.target-filter .el-select{width:150px}.ota-firmware-detail h3{font-size:17px;margin-top:24px}.ota-firmware-detail h4{font-size:14px}@media(max-width:600px){.facts{grid-template-columns:105px minmax(0,1fr);gap:8px}.target-filter .el-input,.target-filter .el-select{width:100%}}</style>
